def tool_error_message(tool_call: Dict[str, Any], error: Exception) -> Dict[str, Any]:
    """Close a pending OpenAI tool call even when local execution fails."""
    call_id = str(tool_call.get("id", "")).strip()
    if not call_id:
        raise ValueError("A failed tool call must carry a tool-call id")
    tool_name = str(tool_call.get("name", "unknown_tool"))
    return {
        "role": "tool",
        "tool_call_id": call_id,
        "name": tool_name,
        "content": (
            f"ERROR: Tool **{tool_name}** failed with error: {error}. "
            "Please check the tool call."
        ),
    }
